const SHA=/^[a-f0-9]{40}$/;
function clean(v,max=180){return String(v||"").replace(/[\u0000-\u001f\u007f]/g," ").trim().slice(0,max);}
export const AVATAR_RELEASE_EVIDENCE_BUNDLE_V1="laneriq-avatar-release-evidence-bundle-v1";

export function buildAvatarReleaseEvidenceBundle({releaseId,mainSha,productionRuntimeSha,buildId,issuerRegistryRevision,evidenceRegistryRevision,capabilityDecisions=[],probeEvaluations=[],leases=[],createdAtMs=Date.now()}={}){
  const main=clean(mainSha,40).toLowerCase(),runtime=clean(productionRuntimeSha,40).toLowerCase();if(!clean(releaseId,120)||!SHA.test(main)||!SHA.test(runtime)||!clean(buildId,120))throw new Error("AVATAR_RELEASE_EVIDENCE_CONTEXT_INVALID");return{contract:AVATAR_RELEASE_EVIDENCE_BUNDLE_V1,bundleId:`release-evidence:${clean(releaseId,80)}:${main.slice(0,12)}`,releaseId:clean(releaseId,120),mainSha:main,productionRuntimeSha:runtime,buildId:clean(buildId,120),issuerRegistryRevision:Math.max(0,Number(issuerRegistryRevision)||0),evidenceRegistryRevision:Math.max(0,Number(evidenceRegistryRevision)||0),capabilityDecisions:(Array.isArray(capabilityDecisions)?capabilityDecisions:[]).slice(0,16),probeEvaluations:(Array.isArray(probeEvaluations)?probeEvaluations:[]).slice(0,32),leases:(Array.isArray(leases)?leases:[]).slice(0,16),createdAtMs:Number(createdAtMs)||Date.now(),automaticProductionMutation:false,privacy:{rawPromptIncluded:false,rawMemoryIncluded:false,rawPrivateKeyIncluded:false,rawProviderCredentialIncluded:false}};
}

export function evaluateAvatarReleaseEvidenceBundle(bundle,{expectedMainSha,requiredCapabilities=[],nowMs=Date.now()}={}){
  const reasons=[];if(bundle?.contract!==AVATAR_RELEASE_EVIDENCE_BUNDLE_V1)reasons.push("RELEASE_EVIDENCE_BUNDLE_INVALID");const expected=clean(expectedMainSha,40).toLowerCase();if(!SHA.test(expected)||bundle?.mainSha!==expected)reasons.push("RELEASE_MAIN_SHA_MISMATCH");if(bundle?.productionRuntimeSha!==bundle?.mainSha)reasons.push("PRODUCTION_RUNTIME_SHA_MISMATCH");if(!(Number(bundle?.issuerRegistryRevision)>0))reasons.push("ISSUER_REGISTRY_REVISION_REQUIRED");if(!(Number(bundle?.evidenceRegistryRevision)>0))reasons.push("EVIDENCE_REGISTRY_REVISION_REQUIRED");const caps=Array.isArray(requiredCapabilities)?requiredCapabilities:[];for(const cap of caps){const decision=(bundle?.capabilityDecisions||[]).find(x=>x?.capability===cap);if(!decision||decision?.promote!==true)reasons.push(`CAPABILITY_NOT_PROMOTED:${cap}`);const lease=(bundle?.leases||[]).find(x=>x?.capability===cap&&x?.status==="active");if(!lease||Number(lease?.expiresAtMs)<=Number(nowMs||Date.now()))reasons.push(`CAPABILITY_LEASE_INVALID:${cap}`);}if(!(bundle?.probeEvaluations||[]).some(x=>x?.pass===true&&x?.headSha===bundle?.mainSha))reasons.push("PRODUCTION_PROBE_EVIDENCE_REQUIRED");return{contract:"laneriq-avatar-release-evidence-evaluation-v1",pass:reasons.length===0,reasons,mainSha:bundle?.mainSha||"",productionRuntimeSha:bundle?.productionRuntimeSha||"",requiredCapabilities:caps.slice(0,16),auditable:true};
}

export function buildAvatarReleaseRollbackEvidence({bundle,reason="release-evidence-invalidated",invalidCapabilities=[]}={}){if(bundle?.contract!==AVATAR_RELEASE_EVIDENCE_BUNDLE_V1)throw new Error("AVATAR_RELEASE_EVIDENCE_BUNDLE_REQUIRED");return{contract:"laneriq-avatar-release-rollback-evidence-v1",releaseId:bundle.releaseId,mainSha:bundle.mainSha,reason:clean(reason,160),invalidCapabilities:(Array.isArray(invalidCapabilities)?invalidCapabilities:[]).slice(0,16).map(x=>clean(x,64)),action:"disable-live-capability-and-return-to-code-ready",requiresProductionReleaseControl:true,automaticRollback:false,preserveEvidenceHistory:true};}

export function getAvatarReleaseEvidenceBundleReadiness(){return{contract:AVATAR_RELEASE_EVIDENCE_BUNDLE_V1,mainRuntimeShaEquality:true,registryRevisionBinding:true,capabilityLeaseBinding:true,probeBinding:true,rollbackEvidence:true,codeReady:true,productionEvidenceBundleLive:false};}
